#!/bin/sh
bin=$(cd "$(dirname "$0")" && pwd)
echo "kith-ask $1 | task=$3 | person=$KITH_PERSON agent=$KITH_AGENT ask-token=${KITH_ASK_TOKEN:+set} run-token=${KITH_RUN_TOKEN:+set}" >> "$DIFFTEST_FAKELOG"
case "$3" in
  FAIL*) echo "boom: the helper broke" >&2; exit 1 ;;
  SYNC*) echo "kith: this Mac is out of sync with the Kith cloud" >&2; exit 1 ;;
  EMPTY*) exit 0 ;;
  OUTFAIL*) echo "stdout reason"; exit 1 ;;
  LONGERR*) python3 -c "print('e' * 3000)" >&2; exit 1 ;;
esac
res=$(python3 "$bin/kith-auth" resolve "$1" --person "$KITH_PERSON" --via "$KITH_AGENT" --take-once 2>&1) || { echo "kith-auth: $res" >&2; exit 1; }
verdict=$(printf '%s' "$res" | python3 -c 'import json, sys
r = json.load(sys.stdin)
print("held" if r.get("held") else "ok" if r.get("allowed") else "no: %s" % r.get("why"))')
case $verdict in
  held) echo "kith: this Mac is out of sync with the Kith cloud" >&2; exit 1 ;;
  ok) echo "$1 answers: $3" ;;
  *) echo "kith: $verdict" >&2; exit 1 ;;
esac

